mapper.select:
SELECT d.id, d.device_code, d.device_name, d.device_type, d.building_id, d.floor, d.altitude, d.status, d.install_time, d.created_at, ST_X(d.location) AS lon, ST_Y(d.location) AS lat FROM t_device AS d
AND d.building_id = #{buildingId}
AND d.device_type = #{deviceType}
ORDER BY d.building_id, d.id

SELECT d.id, d.device_code, d.device_name, d.device_type, d.building_id, d.floor, d.altitude, d.status, ST_X(d.location) AS lon, ST_Y(d.location) AS lat FROM t_device AS d
AND (d.device_name ILIKE '%' || #{keyword} || '%' OR d.device_code ILIKE '%' || #{keyword} || '%')
AND d.device_type = #{deviceType}
AND d.status = #{status}
AND d.building_id = #{buildingId}
ORDER BY d.id
